// Generated by `npm run chat:probe -- --from-trace` (T-0174) from 2026-10-16.jsonl:1210,2026-10-16.jsonl:1211,2026-10-16.jsonl:1212,2026-10-16.jsonl:1213,2026-10-16.jsonl:1214 (catalog agent-ui).
// Keyless: the recorded model rounds replay through the real produce(), then the probe checks run with
// no browser. The browser leg is `npm run chat:probe -- --replay lexicographer-haiku-messages-brace.json` from this folder.
import { readFileSync } from 'node:fs'
import { expect, it } from 'vitest'
import { parseProbeFixture } from '../model.ts'
import { offlineReplay } from '../trace.ts'

// expectedFail: round 8 cluster A (T-0319, 2026-10-16-r8-matrix :174-:178, Haiku 5.5). On "Play again." round 1 calls
// render_surface with `messages` as a JSON string that lost an object opener (`},"guessBtn","component":"Button"`), so
// it is PARSE and T-0304 cannot decode it; round 2 answers in prose (ACTION_NOT_APPLIED) and round 3 resends the same
// broken string, so the turn ships no surface (SURFACE_DEGRADED). Pinned to today's behavior.
const trace = (record) => record.lines.map((l) => JSON.parse(l)).map((l) => l.a2uiMeta?.trace).find((t) => t !== undefined)
const surfaceLines = (record) => record.lines.map((l) => JSON.parse(l)).filter((m) => m.createSurface ?? m.updateComponents ?? m.updateDataModel)

it('lexicographer-haiku-messages-brace: a malformed messages string on Play again is PARSE twice and the new game never ships', async () => {
  const fixture = parseProbeFixture(readFileSync(new URL('./lexicographer-haiku-messages-brace.json', import.meta.url), 'utf8'))
  const report = await offlineReplay(fixture, process.cwd())
  expect(report.failed).toEqual([])
  expect(trace(report.records[4])).toMatchObject({ rounds: 3, failureCodes: ['PARSE', 'SURFACE_DEGRADED'] })
  expect(surfaceLines(report.records[4])).toEqual([])
})
